const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;

export const runScenario = (scenario: Scenario): ScenarioOutput => {
  const quoteStep = scenario.steps[0] as QuoteStep;
  const basePremium = quoteStep.items.length === 0 ? 0 : 100;
  const premium =
    basePremium + basePremium * FIRST_INSURANCE_RATE + PROCESSING_FEE;
  return { results: [{ premium }] };
};
